function field(string $name,string $label,$value='',string $type='text',bool $required=true,int $max=255): void { if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST[$name]))$value=$_POST[$name];?><label><?=e($label)?><input name="<?=e($name)?>" type="<?=e($type)?>" value="<?=e($value)?>" <?= $required?'required':'' ?> maxlength="<?=$max?>" <?= $name==='age'?'min="0" max="130"':($name==='experience'?'min="0" max="80"':'') ?>></label><?php }
function area(string $name,string $label,$value='',bool $required=true,int $max=5000): void {if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST[$name]))$value=$_POST[$name];?><label class="wide"><?=e($label)?><textarea name="<?=e($name)?>" rows="3" maxlength="<?=$max?>" <?=$required?'required':''?>><?=e($value)?></textarea></label><?php }
function select_field(string $name,string $label,array $options,$selected=''): void {if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST[$name]))$selected=$_POST[$name];?><label><?=e($label)?><select name="<?=e($name)?>" required><?php foreach($options as $value=>$text):?><option value="<?=e($value)?>" <?=(string)$value===(string)$selected?'selected':''?>><?=e($text)?></option><?php endforeach;?></select></label><?php }
function search_box(string $placeholder): void {?><form method="get" class="search-form"><span>⌕</span><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="<?=e($placeholder)?>" aria-label="<?=e($placeholder)?>"><button class="button small secondary">Search</button></form><?php }
function action_form(string $action,int $id,string $label,string $class='secondary',bool $confirm=false): void {?><form method="post" class="inline" <?=$confirm?'data-confirm="Are you sure? This action changes hospital records."':''?>><?=csrf()?><input type="hidden" name="action" value="<?=e($action)?>"><input type="hidden" name="id" value="<?=$id?>"><button class="button small <?=e($class)?>"><?=e($label)?></button></form><?php }
function appointment_rows(array $u,int $limit=0): array {
    $where='1=1';$params=[];
    if($u['role']==='patient'){$where='p.user_id=?';$params=[$u['id']];}
    if($u['role']==='doctor'){$where='d.user_id=?';$params=[$u['id']];}
    return rows("SELECT a.*,pu.name patient_name,du.name doctor_name,d.specialization FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN users pu ON pu.id=p.user_id JOIN doctors d ON d.id=a.doctor_id JOIN users du ON du.id=d.user_id WHERE $where ORDER BY a.appointment_date DESC,a.appointment_time DESC".($limit?' LIMIT '.(int)$limit:''),$params);
}
function appointment_table(array $appointments,bool $actions=true): void {global $u;?><div class="table-scroll"><table><thead><tr><th>Patient</th><th>Doctor</th><th>Date & time</th><th>Status</th><?php if($actions):?><th>Action</th><?php endif;?></tr></thead><tbody><?php foreach($appointments as $a):?><tr><td><div class="person"><span class="avatar blue"><?=e(substr($a['patient_name'],0,1))?></span><div><strong><?=e($a['patient_name'])?></strong><small>PT-<?=str_pad($a['patient_id'],4,'0',STR_PAD_LEFT)?></small></div></div></td><td><strong><?=e($a['doctor_name'])?></strong><small><?=e($a['specialization'])?></small></td><td><?=e(date('M d, Y',strtotime($a['appointment_date'])))?><small><?=e(substr($a['appointment_time'],0,5))?> · #<?=e($a['id'])?></small></td><td><?=badge($a['status'])?></td><?php if($actions):?><td><div class="row-actions"><?php if(ROLE==='receptionist'):?><a class="button small secondary" href="?edit=<?=$a['id']?>#appointment-form">Edit</a><?php if(in_array($a['status'],['Pending','Confirmed']))action_form('appointment_cancel',$a['id'],'Cancel','danger',true);?><?php elseif(ROLE==='doctor' && in_array($a['status'],['Pending','Confirmed'])):?><form method="post" class="inline"><?=csrf()?><input type="hidden" name="action" value="appointment_status"><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="Completed"><button class="button small secondary">Complete</button></form><?php else:?>—<?php endif;?></div></td><?php endif;?></tr><?php endforeach;?><?php if(!$appointments):?><tr><td colspan="5" class="empty">No appointments yet. Your upcoming care will appear here.</td></tr><?php endif;?></tbody></table></div><?php }
